class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_td = False
        self.cell = []
        self.cells = []
        self.rows = []
        self.in_tr = False
    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.in_tr = True
            self.cells = []
        elif tag == 'td' and self.in_tr:
            self.in_td = True
            self.cell = []
    def handle_data(self, data):
        if self.in_td:
